CSS='.page{max-width:680px;margin:0 auto;padding:32px 20px 24px}\n.back{display:inline-flex;align-items:center;min-height:44px;color:var(--accent-ink);font-weight:600}\n.page h1{font:650 clamp(30px,5vw,42px)/1.1 var(--sans);letter-spacing:-.03em;margin-top:6px}\n.lede{margin:12px 0 0;color:var(--ink2);font-size:18px;max-width:56ch}\nform{margin-top:24px;display:grid;gap:14px}\nfieldset.step{margin:0;padding:20px 20px 22px;background:var(--surface);border:1px solid var(--line);border-radius:20px;box-shadow:var(--shadow);min-width:0}\nlegend{float:left;width:100%;display:flex;align-items:center;gap:12px;padding:0;font:650 19px var(--sans);letter-spacing:-.02em}\nlegend+*{clear:both}\nlegend .n{display:grid;place-items:center;width:32px;height:32px;border-radius:50%;background:var(--accent-t);color:var(--accent-ink);font:700 15px var(--sans)}\nfieldset label:first-of-type{margin-top:12px}\n.prow{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,1fr) 44px;gap:10px;align-items:end;margin-top:10px}\n.prow.head{margin-top:14px;font-weight:650;font-size:15px;align-items:center}\n.prow input[type=text]{margin-top:0}\n.prow .x{width:44px;height:48px;border:1px solid var(--line2);border-radius:14px;background:var(--surface);color:var(--ink2);font:600 22px var(--sans);cursor:pointer;line-height:1}\n.prow .x:hover{background:var(--bad-t);color:var(--bad);border-color:var(--bad)}\n.sumline{margin:14px 0 0;padding:10px 14px;border-radius:14px;background:var(--idle-t);color:var(--ink2);min-height:44px;display:flex;align-items:center}\n.sumline:empty{min-height:0;padding:0;background:none;margin:0}\n.sumline.ok{background:var(--ok-t);color:var(--ok)}\n.sumline.warn{background:var(--warn-t);color:var(--warn)}\n.actions{margin-top:4px}\n.actions .btn{width:100%;font-size:18px;min-height:54px}\n.queue{margin-top:30px;padding:18px 20px;background:var(--surface);border:1px solid var(--line);border-radius:20px}\n.queue h2{font:650 19px var(--sans)}\n.queue p{margin:6px 0 0;color:var(--ink2)}\n.queue .row{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}\n#status{margin:18px 0 0;padding:14px 18px;border-radius:16px;background:var(--idle-t);color:var(--ink);min-height:48px}\n#status:empty{min-height:0;padding:0;background:none;margin:0}\n#status.ok{background:var(--ok-t);color:var(--ok)}\n#status.err{background:var(--bad-t);color:var(--bad)}\n.receipt{margin-top:18px;padding:18px 20px;background:var(--ok-t);border-radius:20px}\n.receipt h2{font:650 19px var(--sans);color:var(--ok)}\n.receipt p{margin:4px 0 10px;color:var(--ink)}\n.receipt summary{cursor:pointer;min-height:44px;display:flex;align-items:center;font-weight:600}\n.receipt pre{white-space:pre-wrap;overflow-wrap:anywhere;margin:6px 0 0;padding:12px;background:var(--surface);border:1px solid var(--line);border-radius:12px;font:13px/1.5 var(--mono)}\n.help{margin-top:26px}\n.help a{display:inline-flex;align-items:center;min-height:44px;color:var(--accent-ink);font-weight:600}\n@media (max-width:640px){.page{padding:22px 16px 18px}.prow{grid-template-columns:minmax(0,1fr) minmax(0,.8fr) 44px;gap:8px}}'
def rd(p): return open(p,encoding='utf8').read()
def wr(p,s): open(p,'w',encoding='utf8',newline='').write(s)
def sub(f,a,b):
    t=rd(S+f); assert t.count(a)==1,(f,a,t.count(a)); wr(S+f,t.replace(a,b))
