L=rd(S+'i18n.js').split('\n'); seen=set()
for i,l in enumerate(L):
    m=re.match(r'^(\s+)([a-z0-9_]+): (\[.*\])(,?)\s*$',l)
    if m and m.group(2) in E:
        a=json.loads(m.group(3)); k=m.group(2); a[0],a[1]=E[k]; seen.add(k)
        L[i]='%s%s: %s%s'%(m.group(1),k,json.dumps(a,ensure_ascii=False),m.group(4))
assert seen==set(E),set(E)-seen
j=[i for i,l in enumerate(L) if re.match(r'\s+card_send:',l)][0]
L[j+1:j+1]=['    %s: %s,'%(k,json.dumps(v,ensure_ascii=False)) for k,v in NEW.items()]
wr(S+'i18n.js','\n'.join(L))
for f in glob.glob(S+'*.html'):
    s=rd(f)
    s2=re.sub(r'(<([a-z0-9]+)[^>]*?data-i18n="([a-z0-9_]+)"[^>]*)>([^<]*)(</\2>)',lambda m:(m.group(1)+'>'+html.escape(E[m.group(3)][0],quote=False)+m.group(5)) if m.group(3) in E else m.group(0),s)
    if s2!=s: wr(f,s2)
